const { execSync } = require('child_process')
const fs = require('fs')
const path = require('path')

const scriptsFolder = __dirname

const files = fs.readdirSync(scriptsFolder)
let f
let filename
for (f of files) {
  filename = path.join(scriptsFolder, f)
  if (filename == __filename) continue
  if (filename.endsWith('.js')) {
    console.log(filename)
    try {
      execSync(`node ${filename}`,
      {stdio: 'inherit'})
    } catch (e) {
      //pass
    }
  }
}